package zone.moddev.mc.ironagearchitecture.probe;

import java.util.*;
import java.util.concurrent.*;
import java.nio.file.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.*;
import net.minecraft.entity.player.*;
import net.minecraft.init.*;
import net.minecraft.inventory.ClickType;
import net.minecraft.item.ItemStack;
import net.minecraft.util.*;
import net.minecraft.util.math.*;
import net.minecraft.world.*;
import net.minecraftforge.common.util.FakePlayerFactory;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.gameevent.TickEvent;
import zone.moddev.mc.ironagearchitecture.*;
import zone.moddev.mc.ironagearchitecture.block.*;
import zone.moddev.mc.ironagearchitecture.roof.*;
import zone.moddev.mc.ironagearchitecture.client.*;

/** Real client GUI/clipboard traffic and a disposable five-house review world. */
public final class RoofDesignClientProbe {
    private int phase,ticks,shot,actions;private Future<?> pending;private final ArchitectWorkbench.Desk[] desks=new ArchitectWorkbench.Desk[5];
    private final Map<String,Object> result=new LinkedHashMap<>();private final List<String> shots=new ArrayList<>();private BlockPos windowAt,coverAt;
    private static void require(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(e.phase!=TickEvent.Phase.END||phase==99)return;try{advance();}catch(Throwable failure){failure.printStackTrace();finish(failure.toString());}}
    private void next(int p){phase=p;ticks=0;System.out.println("IAA_ROOF_DESIGN_PHASE "+p);}
    private boolean done()throws Exception{if(pending==null)return true;if(!pending.isDone())return false;pending.get();pending=null;return true;}
    private void advance()throws Exception{Minecraft mc=Minecraft.getMinecraft();ticks++;if(ticks>1600)throw new IllegalStateException("Roof design timeout in phase "+phase+"; "+(desks[0]==null?"":desks[0].status));
        if(phase==0&&mc.currentScreen instanceof GuiMainMenu&&ticks>50){mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.showInventoryAchievementHint=false;String name=System.getProperty("iaa.previewName","Roof Design Preview");require(!new java.io.File(mc.mcDataDir,"saves/"+name).exists(),"fresh preview world");mc.launchIntegratedServer(name,name,new WorldSettings(137,GameType.CREATIVE,false,false,WorldType.FLAT));next(1);return;}
        if(phase==1&&mc.player!=null){mc.displayGuiScreen(null);pending=mc.getIntegratedServer().addScheduledTask(()->scene(mc));next(2);return;}
        if(phase==2&&done()&&ticks>40){teleport(mc,-33.5,15,-1,0,35);next(3);return;}
        if(phase==3&&ticks>20){BlockPos p=desks[0].getPos();teleport(mc,p.getX()+.5,p.getY(),p.getZ()-2,0,35);next(4);return;}
        if(phase==4&&ticks>15){openBench(mc);next(5);return;}
        if(phase==5&&ticks>15&&mc.currentScreen instanceof WorkbenchClient.Screen&&WorkbenchClient.latest!=null&&WorkbenchClient.latest.plan!=null){press(mc,3);next(6);return;}
        if(phase==6&&ticks>15&&WorkbenchClient.latest.preview){press(mc,7);next(7);return;}
        if(phase==7&&ticks>15){capture(mc,"01-roof-settings.png");press(mc,7);press(mc,25);next(8);return;}
        if(phase==8&&ticks>20&&mc.player.openContainer.getSlot(27).getHasStack()){require(desks[0].drawing!=null&&!desks[0].isInvalid(),"clipboard appearance preserves bench");mc.playerController.windowClick(mc.player.openContainer.windowId,27,0,ClickType.QUICK_MOVE,mc.player);actions++;next(9);return;}
        if(phase==9&&ticks>20){int slot=-1;for(int i=0;i<9;i++){ItemStack s=mc.player.inventory.getStackInSlot(i);if(s!=null&&s.getItem()==ArchitectureBlocks.ROOF_CLIPBOARD)slot=i;}require(slot>=0,"physical clipboard extracted to hotbar");mc.player.inventory.currentItem=slot;mc.player.closeScreen();mc.playerController.updateController();mc.displayGuiScreen(new RoofClipboardScreen(mc.player.getHeldItemMainhand()));next(10);return;}
        if(phase==10&&ticks>20&&WorkbenchClient.latest.clipboard){capture(mc,"02-clipboard-features.png");press(mc,31);next(11);return;}
        if(phase==11&&ticks>15){capture(mc,"03-clipboard-roof-controls.png");mc.player.closeScreen();RoofPlan p=WorkbenchClient.latest.plan;roofAim(mc,p,7,-32);next(12);return;}
        if(phase==12&&ticks>20){require(WorkbenchClient.pointClipboard(mc.player.getHeldItemMainhand(),mc.player),"pointing at unbuilt ghost");actions++;next(13);return;}
        if(phase==13&&ticks>25&&WorkbenchClient.latest.plan.features.size()==2){result.put("clipboardGhostPoint",true);camera(mc,-45,24,-8,-33,18,4);next(14);return;}
        if(phase==14&&ticks>40){capture(mc,"04-personal-roof-preview.png");BlockPos b=desks[0].getPos();teleport(mc,b.getX()+.5,b.getY(),b.getZ()-2,0,35);next(15);return;}
        if(phase==15&&ticks>20){openBench(mc);next(16);return;}
        if(phase==16&&ticks>20&&mc.currentScreen instanceof WorkbenchClient.Screen){require(WorkbenchClient.latest.canBuild,WorkbenchClient.latest.status);press(mc,4);next(17);return;}
        if(phase==17&&ticks>30&&!desks[0].active&&desks[0].index>0){mc.player.closeScreen();coverAim(mc);pending=mc.getIntegratedServer().addScheduledTask(()->{EntityPlayerMP actor=serverPlayer(mc);actor.setGameType(GameType.SURVIVAL);actor.capabilities.allowFlying=true;actor.capabilities.isFlying=true;actor.sendPlayerAbilities();ItemStack stack=RoofConstruction.coverItem(3);stack.stackSize=64;actor.inventory.setInventorySlotContents(4,stack);actor.inventoryContainer.detectAndSendChanges();});next(90);return;}
        if(phase==90&&done()&&ticks>25){mc.player.inventory.currentItem=4;mc.playerController.updateController();RayTraceResult hit=ray(mc);require(hit!=null&&hit.getBlockPos().equals(coverAt),"new frame receives actual covering ray");require(mc.player.getHeldItemMainhand()!=null,"covering supply synchronized");mc.playerController.processRightClickBlock(mc.player,mc.world,mc.player.getHeldItemMainhand(),coverAt,hit.sideHit,hit.hitVec,EnumHand.MAIN_HAND);actions++;next(91);return;}
        if(phase==91&&ticks>25){RoofCell c=RoofData.get(mc.world).at(mc.world,coverAt);require(c.parts.stream().anyMatch(p->p.kind==RoofPart.COVER&&p.material==3),"native fitting changes typed covering");require(mc.player.getHeldItemMainhand()!=null&&mc.player.getHeldItemMainhand().stackSize==63,"one covering consumed");mc.player.inventory.currentItem=3;mc.playerController.updateController();mc.player.setSneaking(true);mc.getConnection().sendPacket(new net.minecraft.network.play.client.CPacketEntityAction(mc.player,net.minecraft.network.play.client.CPacketEntityAction.Action.START_SNEAKING));next(92);return;}
        if(phase==92&&ticks>15){RayTraceResult hit=ray(mc);require(hit!=null,"roof covering has an exact target");mc.playerController.processRightClickBlock(mc.player,mc.world,null,hit.getBlockPos(),hit.sideHit,hit.hitVec,EnumHand.MAIN_HAND);actions++;next(93);return;}
        if(phase==93&&ticks>25){RoofCell c=RoofData.get(mc.world).at(mc.world,coverAt);require(c.parts.stream().anyMatch(p->p.kind==RoofPart.COVER&&p.material==0),"native strip leaves bare rafters");require(mc.player.inventory.getStackInSlot(4).stackSize==64,"covering recovered once");result.put("nativeCoverFitAndRecovery",true);mc.player.setSneaking(false);mc.getConnection().sendPacket(new net.minecraft.network.play.client.CPacketEntityAction(mc.player,net.minecraft.network.play.client.CPacketEntityAction.Action.STOP_SNEAKING));pending=mc.getIntegratedServer().addScheduledTask(()->{EntityPlayerMP actor=serverPlayer(mc);actor.setGameType(GameType.CREATIVE);actor.capabilities.allowFlying=true;actor.capabilities.isFlying=true;actor.sendPlayerAbilities();actor.inventory.setInventorySlotContents(4,null);actor.inventoryContainer.detectAndSendChanges();finishScene(mc);});next(18);return;}
        if(phase==18&&done()&&ticks>100){verify(mc);windowAim(mc);next(19);return;}
        if(phase==19&&done()&&ticks>25){Vec3d a=mc.player.getPositionEyes(1),b=a.add(mc.player.getLook(1).scale(5));RayTraceResult hit=mc.world.rayTraceBlocks(a,b,false,false,false);require(hit!=null,"native window targeting");windowAt=hit.getBlockPos();RoofCell c=RoofData.get(mc.world).at(mc.world,windowAt);require(c!=null&&!c.windows.isEmpty(),"native rooflight hit");mc.playerController.processRightClickBlock(mc.player,mc.world,null,windowAt,hit.sideHit,hit.hitVec,EnumHand.MAIN_HAND);actions++;next(20);return;}
        if(phase==20&&ticks>25){RoofCell c=RoofData.get(mc.world).at(mc.world,windowAt);require(c!=null&&c.windows.stream().anyMatch(n->n.open),"rooflight opens through player packet");result.put("nativeRooflightOpen",true);pending=mc.getIntegratedServer().addScheduledTask(()->{WorldServer w=mc.getIntegratedServer().worldServerForDimension(0);EntityPlayerMP p=serverPlayer(mc);p.inventory.setInventorySlotContents(0,new ItemStack(ArchitectureBlocks.ROOF_CLIPBOARD));RoofClipboardItem.bind(p.inventory.getStackInSlot(0),desks[0].drawing,0);p.inventory.currentItem=0;p.inventoryContainer.detectAndSendChanges();try{w.saveAllChunks(true,null);}catch(net.minecraft.world.MinecraftException ex){throw new IllegalStateException(ex);}});next(21);return;}
        if(phase==21&&done()&&ticks>30){double[][] views={{-25,18,-21,-20,17,4},{-45,19,-10,-33,17,4},{-34.5,15.1,4,-34.5,17.5,1.1},{-15.5,15.1,5,-11,19,5},{2,19,-13,7,18,4},{25,19,-12,26,18,4},{-22,40,-4,-1,17,4},{-30.5,15.1,5,-36,17,5},{-39,14,-2,-35,15.7,0}};if(shot==views.length){verify(mc);finish("");return;}double[] v=views[shot];camera(mc,v[0],v[1],v[2],v[3],v[4],v[5]);next(22);return;}
        if(phase==22&&ticks>55){capture(mc,new String[]{"05-street.png","06-gabled-dormer.png","07-dormer-interior.png","08-open-vault.png","09-mansard-shed.png","10-tall-casement.png","11-overhead.png","12-attic-room.png","13-eaves-guttering.png"}[shot++]);next(21);}
    }
    private static EntityPlayerMP serverPlayer(Minecraft mc){return mc.getIntegratedServer().getPlayerList().getPlayerByUUID(mc.player.getUniqueID());}
    private void scene(Minecraft mc){WorldServer w=mc.getIntegratedServer().worldServerForDimension(0);w.setWorldTime(6000);w.getGameRules().setOrCreateGameRule("doDaylightCycle","false");w.getGameRules().setOrCreateGameRule("doWeatherCycle","false");w.getGameRules().setOrCreateGameRule("doFireTick","false");w.getGameRules().setOrCreateGameRule("doMobSpawning","false");for(int x=-50;x<65;x++)for(int z=-20;z<18;z++){w.getChunkFromBlockCoords(new BlockPos(x,9,z));for(int y=4;y<=9;y++)w.setBlockState(new BlockPos(x,y,z),(y==9?(z<0?Blocks.GRAVEL:Blocks.GRASS):Blocks.DIRT).getDefaultState(),2);}
        EntityPlayerMP builder=FakePlayerFactory.getMinecraft(w);builder.capabilities.isCreativeMode=true;builder.setPosition(-55,30,-20);
        for(int i=0;i<5;i++){int ox=-40+i*20,wood=new int[]{5,1,5,0,0}[i];for(int x=ox;x<=ox+12;x++)for(int z=0;z<=9;z++){w.setBlockState(new BlockPos(x,9,z),Blocks.STONEBRICK.getDefaultState(),2);if(x==ox||x==ox+12||z==0||z==9)for(int y=10;y<=14;y++)w.setBlockState(new BlockPos(x,y,z),ArchitectureBlocks.SMART_COB.getStateFromMeta(1),2);if((x>ox&&x<ox+12&&z>0&&z<9)||i==4)w.setBlockState(new BlockPos(x,14,z),ArchitectureBlocks.findFloor(ArchitectureBlocks.WOODS[wood],FloorShape.FULL,null).getDefaultState(),2);}
            BlockPos door=new BlockPos(ox+6,10,0);w.setBlockToAir(door);w.setBlockToAir(door.up());net.minecraft.item.ItemDoor.placeDoor(w,door,EnumFacing.NORTH,Blocks.SPRUCE_DOOR,false);for(int x:new int[]{ox+3,ox+9})w.setBlockState(new BlockPos(x,11,0),ArchitectureBlocks.findWindow("dark_oak",1,false,true,false).getDefaultState().withProperty(WindowBlock.FACING,EnumFacing.NORTH),2);
            BlockPos at=new BlockPos(ox+6,15,5);w.setBlockState(at,ArchitectureBlocks.ARCHITECTS_WORKBENCH.getDefaultState(),3);ArchitectWorkbench.Desk d=(ArchitectWorkbench.Desk)w.getTileEntity(at);desks[i]=d;RoofConstruction.detect(d);RoofPlan p=d.drawing;p.alongX=true;p.wood=wood;p.frame=i==1?2:1;p.edge=i==0?2:i==1?0:1;if(i==1)p.base=1;if(i==2)p.mansard=3;if(i==3)p.mansard=1;
            if(i==0||i==2||i==3){RoofFeature f=new RoofFeature();f.id=1;f.type=i==2?RoofFeature.SHED:RoofFeature.GABLE;f.u=i==2||i==3?0:1;f.v=ox+(i==2?3:4);f.width=i==2?7:i==3?1:3;f.height=i==3?2:1;f.cover=i==2?3:1;f.wood=wood;p.features.add(f);}
            if(i==4){p.version=1;p.base=0;p.pitch=1;}RoofPlanner.solve(p);require(p.valid(),"house "+i+": "+p.error);RoofData.get(w).draft(p);if(i>0)require(RoofConstruction.start(d,builder),"house "+i+": "+d.status);
        }
        desks[0].give(new ItemStack(Items.PAPER));desks[0].give(new ItemStack(Blocks.PLANKS));EntityPlayerMP p=serverPlayer(mc);p.setGameType(GameType.CREATIVE);p.capabilities.allowFlying=true;p.capabilities.isFlying=true;p.sendPlayerAbilities();w.setSpawnPoint(new BlockPos(-22,10,-8));ProbeShapes.flush(w);
    }
    private void finishScene(Minecraft mc){WorldServer w=mc.getIntegratedServer().worldServerForDimension(0);EntityPlayerMP actor=FakePlayerFactory.getMinecraft(w);actor.capabilities.isCreativeMode=true;actor.setPosition(-55,30,-20);for(int i=0;i<5;i++){ArchitectWorkbench.Desk d=desks[i];require(!d.active,"other roof completed");RoofPlan p=d.drawing;Map<Long,RoofCell> all=RoofData.get(w).owned(w,p);if(p.version==2){Map<Long,RoofCell> next=new TreeMap<>();for(Map.Entry<Long,RoofCell> e:all.entrySet()){RoofCell c=e.getValue();List<RoofPart> ps=new ArrayList<>();for(RoofPart part:c.parts)ps.add(part.kind==RoofPart.COVER&&part.material==0?part.withMaterial(i==1?2:i==2?3:1):part);next.put(e.getKey(),new RoofCell(c.plan,c.owner,ps,c.windows));}RoofConstruction.changing=true;try{for(Map.Entry<Long,RoofCell> e:next.entrySet())RoofDesignInteraction.write(w,BlockPos.fromLong(e.getKey()),e.getValue());}finally{RoofConstruction.changing=false;}}else for(Map.Entry<Long,RoofCell> e:all.entrySet())if(e.getValue().coverable())w.setBlockState(BlockPos.fromLong(e.getKey()),RoofFrameBlock.state(p.wood,1),3);
            // The ordinary gable infill is deliberately separate from the owned roof.
            for(int x:new int[]{p.minX-1,p.maxX+1})for(int z=p.minZ;z<=p.maxZ;z++){double h=p.version==2?RoofDesignPlanner.surface(p,z+.5):15.25+Math.min(z-p.minZ,p.maxZ+1-z);for(int y=15;y+1<=h-.125;y++){BlockPos at=new BlockPos(x,y,z);if(w.isAirBlock(at))w.setBlockState(at,ArchitectureBlocks.SMART_COB.getStateFromMeta(1),2);}}
            if(i==0)fitGutters(w,p,actor);
        for(int z:new int[]{p.minZ+1,p.maxZ-1}){BlockPos light=new BlockPos(p.minX+2,p.floorY+1,z);if(w.isAirBlock(light))w.setBlockState(light,Blocks.TORCH.getDefaultState(),3);}}ProbeShapes.flush(w);
    }
    private void fitGutters(WorldServer w,RoofPlan p,EntityPlayerMP actor){int n=0;for(Map.Entry<Long,RoofCell> e:new ArrayList<>(RoofData.get(w).owned(w,p).entrySet()))for(RoofPart board:e.getValue().parts)if(board.kind==RoofPart.FASCIA&&board.facing==EnumFacing.NORTH){BlockPos at=BlockPos.fromLong(e.getKey());RoofMeshes.Mesh m=RoofMeshes.get(new RoofCell(p.id,at,Collections.singletonList(board),Collections.emptyList()),0);for(RoofMeshes.Face face:m.faces)if(face.normal[2]<-.9){double[] c=centre(face);actor.setPosition(at.getX()+c[0],at.getY()+c[1]-actor.getEyeHeight(),at.getZ()+c[2]-2);actor.rotationYaw=0;actor.rotationPitch=0;ItemStack stack=new ItemStack(ArchitectureBlocks.GUTTER,1);actor.setHeldItem(EnumHand.MAIN_HAND,stack);RoofPart hit=RoofDesignInteraction.target(w,at,actor);boolean fitted=RoofGutters.fit(w,at,actor,stack,EnumFacing.NORTH,false);System.out.println("IAA_GUTTER_NATIVE at="+at+" target="+(hit==null?"none":hit.kind+":"+hit.id)+" fitted="+fitted+" eye="+actor.getPositionEyes(1));if(fitted)n++;break;}}result.put("fittedGutters",n);require(n>2,"existing gutter items fit planned fascia");}
    private RayTraceResult ray(Minecraft mc){Vec3d a=SmartThatchBlock.eyes(mc.player);return mc.world.rayTraceBlocks(a,a.add(SmartThatchBlock.look(mc.player).scale(5)),false,false,false);}
    private void coverAim(Minecraft mc){RoofPlan p=desks[0].drawing;for(Map.Entry<Long,RoofCell> e:RoofData.get(mc.world).owned(mc.world,p).entrySet()){BlockPos at=BlockPos.fromLong(e.getKey());if(RoofDesignPlanner.u(p,at)!=p.minZ+1||RoofDesignPlanner.v(p,at)!=p.minX+1||e.getValue().parts.stream().noneMatch(a->a.kind==RoofPart.COVER&&a.material==0))continue;for(RoofMeshes.Face face:RoofMeshes.get(e.getValue(),0).faces)if(face.kind==RoofPart.TIMBER&&face.normal[1]>.4){coverAt=at;aim(mc,at,face,2.5);return;}}throw new IllegalStateException("No bare typed roofing target");}
    private void roofAim(Minecraft mc,RoofPlan p,int u,int v){for(Map.Entry<Long,RoofCell> e:p.cells.entrySet()){BlockPos at=BlockPos.fromLong(e.getKey());if(RoofDesignPlanner.u(p,at)!=u||RoofDesignPlanner.v(p,at)!=v)continue;for(RoofMeshes.Face face:RoofMeshes.drawing(e.getValue()).faces)if(face.kind==RoofPart.COVER&&face.normal[1]>.3){aim(mc,at,face,2.5);return;}}throw new IllegalStateException("No preview roofing target");}
    private void windowAim(Minecraft mc){RoofPlan p=desks[0].drawing;for(Map.Entry<Long,RoofCell> e:RoofData.get(mc.world).owned(mc.world,p).entrySet())for(RoofMeshes.Face face:RoofMeshes.get(e.getValue(),0).faces)if(face.kind==RoofPart.WINDOW&&face.detail==3&&face.normal[1]>.2&&e.getValue().windows.stream().anyMatch(n->!n.vertical&&face.partIndex>=0&&n.id.equals(e.getValue().parts.get(face.partIndex).id))){aim(mc,BlockPos.fromLong(e.getKey()),face,2.2);pending=mc.getIntegratedServer().addScheduledTask(()->{EntityPlayerMP actor=serverPlayer(mc);actor.setHeldItem(EnumHand.MAIN_HAND,null);actor.inventoryContainer.detectAndSendChanges();});return;}throw new IllegalStateException("No rooflight target");}
    private static double[] centre(RoofMeshes.Face face){double[] c=new double[3];for(double[] v:face.vertices)for(int i=0;i<3;i++)c[i]+=v[i]/face.vertices.length;return c;}
    private void aim(Minecraft mc,BlockPos at,RoofMeshes.Face face,double distance){double[] c=centre(face);double x=at.getX()+c[0],y=at.getY()+c[1],z=at.getZ()+c[2];double px=x+face.normal[0]*distance,py=y+face.normal[1]*distance-mc.player.getEyeHeight(),pz=z+face.normal[2]*distance;teleport(mc,px,py,pz,(float)(Math.toDegrees(Math.atan2(z-pz,x-px))-90),(float)-Math.toDegrees(Math.atan2(y-py-mc.player.getEyeHeight(),Math.hypot(x-px,z-pz))));}
    private void openBench(Minecraft mc){mc.player.inventory.currentItem=4;mc.playerController.updateController();BlockPos at=desks[0].getPos();mc.playerController.processRightClickBlock(mc.player,mc.world,null,at,EnumFacing.UP,new Vec3d(at).addVector(.5,1,.5),EnumHand.MAIN_HAND);actions++;}
    private void verify(Minecraft mc){int cells=0,faces=0;for(ArchitectWorkbench.Desk d:desks)for(Map.Entry<Long,RoofCell> e:RoofData.get(d.getWorld()).owned(d.getWorld(),d.drawing).entrySet()){BlockPos at=BlockPos.fromLong(e.getKey());RoofCell c=RoofData.get(mc.world).at(mc.world,at);require(e.getValue().equals(c),"synced profile "+at);net.minecraft.block.state.IBlockState state=mc.world.getBlockState(at);require(RoofDesignInteraction.host(state),"roof host "+at);net.minecraft.client.renderer.block.model.IBakedModel model=mc.getBlockRendererDispatcher().getModelForState(state);require(model instanceof RoofFrameBakedModel,"baked model "+at);List<net.minecraft.client.renderer.block.model.BakedQuad> qs=model.getQuads(state.getBlock().getExtendedState(state,mc.world,at),null,0);require(qs.size()==RoofMeshes.get(c,RoofFrameBlock.cover(state)).faces.size(),"model faces "+at);for(net.minecraft.client.renderer.block.model.BakedQuad q:qs)require(!q.getSprite().getIconName().contains("missingno"),"all sprites resolved");cells++;faces+=qs.size();}result.put("syncedCells",cells);result.put("renderedFaces",faces);}
    private void teleport(Minecraft mc,double x,double y,double z,float yaw,float pitch){mc.gameSettings.hideGUI=false;mc.player.capabilities.allowFlying=true;mc.player.capabilities.isFlying=true;mc.player.motionX=mc.player.motionY=mc.player.motionZ=0;mc.player.setLocationAndAngles(x,y,z,yaw,pitch);mc.player.sendPlayerAbilities();mc.getIntegratedServer().addScheduledTask(()->{EntityPlayerMP p=serverPlayer(mc);p.capabilities.allowFlying=true;p.capabilities.isFlying=true;p.sendPlayerAbilities();p.connection.setPlayerLocation(x,y,z,yaw,pitch);});}
    private void camera(Minecraft mc,double x,double y,double z,double tx,double ty,double tz){mc.displayGuiScreen(null);teleport(mc,x,y,z,(float)(Math.toDegrees(Math.atan2(tz-z,tx-x))-90),(float)-Math.toDegrees(Math.atan2(ty-y-mc.player.getEyeHeight(),Math.hypot(tx-x,tz-z))));mc.gameSettings.hideGUI=true;}
    private void press(Minecraft mc,int id)throws Exception{GuiButton chosen=null;for(java.lang.reflect.Field f:GuiScreen.class.getDeclaredFields())if(List.class.isAssignableFrom(f.getType())){f.setAccessible(true);for(Object o:(List<?>)f.get(mc.currentScreen))if(o instanceof GuiButton&&((GuiButton)o).id==id)chosen=(GuiButton)o;}require(chosen!=null&&chosen.enabled&&chosen.visible,"enabled GUI button "+id);for(java.lang.reflect.Method m:mc.currentScreen.getClass().getDeclaredMethods())if(Arrays.equals(m.getParameterTypes(),new Class<?>[]{GuiButton.class})){m.setAccessible(true);m.invoke(mc.currentScreen,chosen);actions++;return;}throw new IllegalStateException("GUI action absent");}
    private void capture(Minecraft mc,String name){net.minecraft.util.ScreenShotHelper.saveScreenshot(mc.mcDataDir,name,mc.displayWidth,mc.displayHeight,mc.getFramebuffer());shots.add(name);}
    private void finish(String error){if(phase==99)return;int failedPhase=phase;phase=99;Minecraft mc=Minecraft.getMinecraft();result.put("passed",error.isEmpty());result.put("error",error);result.put("phase",failedPhase);result.put("guiActions",actions);if(!error.isEmpty())capture(mc,"failure-phase-"+failedPhase+".png");result.put("screenshots",shots);result.put("runtimeSha256",System.getProperty("iaa.runtimeSha256"));try{Files.write(mc.mcDataDir.toPath().resolve("roof-design-client.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(result).getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){throw new RuntimeException(e);}System.out.println("IAA_CLIENT_PROBE_"+(error.isEmpty()?"PASS":"FAIL")+" roofDesign");mc.shutdown();}
}
